// src/auth/sitzung.ts
var enc2 = new TextEncoder();
var dec2 = new TextDecoder();
var COOKIE = "tw_sitzung";
var SITZUNG_TAGE = 14;
async function schluessel(geheim) {
  return crypto.subtle.importKey("raw", enc2.encode(geheim), { name: "HMAC", hash: "SHA-256" }, false, [
    "sign",
    "verify"
  ]);
}
async function siegeln(geheim, daten, gueltigMs) {
  const nutzlast = b64url(enc2.encode(JSON.stringify({ d: daten, exp: Date.now() + gueltigMs })));
  const sig = await crypto.subtle.sign("HMAC", await schluessel(geheim), enc2.encode(nutzlast));
  return `${nutzlast}.${b64url(new Uint8Array(sig))}`;
}
async function oeffnen(geheim, wert) {
  if (!wert) return null;
  const [nutzlast, sig] = wert.split(".");
  if (!nutzlast || !sig) return null;
  const erwartet = await crypto.subtle.sign("HMAC", await schluessel(geheim), enc2.encode(nutzlast));
  if (!timingSafeEqual(b64url(new Uint8Array(erwartet)), sig)) return null;
  try {
    const inhalt = JSON.parse(dec2.decode(fromB64url(nutzlast)));
    if (!inhalt.exp || inhalt.exp < Date.now()) return null;
    return inhalt.d;
  } catch {
    return null;
  }
}
function ausCookies(header, name) {
  if (!header) return null;
  for (const teil of header.split(";")) {
    const [k, ...rest] = teil.trim().split("=");
    if (k === name) return decodeURIComponent(rest.join("="));
  }
  return null;
}
async function angemeldet(request, geheim) {
  return oeffnen(geheim, ausCookies(request.headers.get("cookie"), COOKIE));
}
async function sitzungsCookie(geheim, nutzer) {
  const wert = await siegeln(geheim, nutzer, SITZUNG_TAGE * 24 * 60 * 60 * 1e3);
  return `${COOKIE}=${encodeURIComponent(wert)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${SITZUNG_TAGE * 24 * 60 * 60}`;
}
var abmeldeCookie = `${COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`;

// src/auth/oauth.ts
