async function handleToken(req, env) {
  let form;
  try {
    form = await req.formData();
  } catch {
    return oauthError("invalid_request", "Body muss application/x-www-form-urlencoded sein.");
  }
  const client = await clientPruefen(req, form, env);
  if (client instanceof Response) return client;
  const grantType = String(form.get("grant_type") ?? "");
  if (grantType === "authorization_code") {
    const code = String(form.get("code") ?? "");
    const verifier = String(form.get("code_verifier") ?? "");
    const redirectUri = String(form.get("redirect_uri") ?? "");
    if (!code) return oauthError("invalid_request", "code fehlt.");
    if (!verifier) return oauthError("invalid_request", "code_verifier fehlt (PKCE ist Pflicht).");
    const kvKey = `ac:${await sha256hex(code)}`;
    const rec = await env.OAUTH_KV.get(kvKey, "json");
    if (!rec) return oauthError("invalid_grant", "Code unbekannt, abgelaufen oder schon benutzt.");
    await env.OAUTH_KV.delete(kvKey);
    if (rec.clientId !== client.client_id) {
      return oauthError("invalid_grant", "Der Code geh\xF6rt zu einem anderen Client.");
    }
    if (redirectUri && redirectUri !== rec.redirectUri) {
      return oauthError("invalid_grant", "redirect_uri stimmt nicht mit der Autorisierung \xFCberein.");
    }
    if (!await verifyPkceS256(verifier, rec.codeChallenge)) {
      return oauthError("invalid_grant", "code_verifier passt nicht zur code_challenge.");
    }
    const { nutzer } = await openJSON(code, rec.sealed);
    return json(
      await tokenAusstellen(env, rec.grantId, client.client_id, nutzer, rec.scope ?? SCOPES)
    );
  }
  if (grantType === "refresh_token") {
    const token = String(form.get("refresh_token") ?? "");
    if (!token) return oauthError("invalid_request", "refresh_token fehlt.");
    const kvKey = `rt:${await sha256hex(token)}`;
    const rec = await env.OAUTH_KV.get(kvKey, "json");
    if (!rec) return oauthError("invalid_grant", "refresh_token unbekannt oder abgelaufen.");
    if (rec.clientId !== client.client_id) {
      return oauthError("invalid_grant", "Das Token geh\xF6rt zu einem anderen Client.");
    }
    const grant = await env.OAUTH_KV.get(`grant:${rec.grantId}`, "json");
    if (!grant || grant.revoked) {
      return oauthError("invalid_grant", "Die Freigabe wurde widerrufen.");
    }
    await env.OAUTH_KV.delete(kvKey);
    const { nutzer } = await openJSON(token, rec.sealed);
    return json(await tokenAusstellen(env, rec.grantId, client.client_id, nutzer, SCOPES));
  }
  return oauthError("unsupported_grant_type", `grant_type '${grantType}' wird nicht unterst\xFCtzt.`);
}
async function handleRevoke(req, env) {
  let form;
  try {
    form = await req.formData();
  } catch {
    return oauthError("invalid_request", "Body muss application/x-www-form-urlencoded sein.");
  }
  const token = String(form.get("token") ?? "");
  if (token) {
    const hash = await sha256hex(token);
    const rec = await env.OAUTH_KV.get(`at:${hash}`, "json") ?? await env.OAUTH_KV.get(`rt:${hash}`, "json");
    await Promise.all([env.OAUTH_KV.delete(`at:${hash}`), env.OAUTH_KV.delete(`rt:${hash}`)]);
    if (rec?.grantId) {
      const grant = await env.OAUTH_KV.get(`grant:${rec.grantId}`, "json");
      if (grant) {
        await env.OAUTH_KV.put(`grant:${rec.grantId}`, JSON.stringify({ ...grant, revoked: true }), {
          expirationTtl: REFRESH_TTL
        });
      }
    }
  }
  return json({});
}
async function bearerPruefen(req, env) {
  const header = req.headers.get("authorization") ?? "";
  if (!header.toLowerCase().startsWith("bearer ")) return null;
  const token = header.slice(7).trim();
  if (!token) return null;
  const rec = await env.OAUTH_KV.get(`at:${await sha256hex(token)}`, "json");
  if (!rec) return null;
  const grant = await env.OAUTH_KV.get(`grant:${rec.grantId}`, "json");
  if (!grant || grant.revoked) return null;
  try {
    const { nutzer } = await openJSON(token, rec.sealed);
    return { nutzer, grantId: rec.grantId, clientId: rec.clientId };
  } catch {
    return null;
  }
}

// src/auth/passwoerter.ts
var enc3 = new TextEncoder();
var MAX_FEHLVERSUCHE = 10;
var SPERRE_SEKUNDEN = 15 * 60;
async function pruefen(passwort, gespeichert) {
  const [verfahren, rundenText, salzText, hashText] = String(gespeichert).split("$");
  if (verfahren !== "pbkdf2" || !rundenText || !salzText || !hashText) return false;
  const runden = Number(rundenText);
  if (!Number.isFinite(runden) || runden < 1e3) return false;
  const hash = await ableiten(passwort, fromB64url(salzText), runden);
  return timingSafeEqual(b64url(hash), hashText);
}
async function ableiten(passwort, salz, runden) {
  const material = await crypto.subtle.importKey("raw", enc3.encode(passwort), "PBKDF2", false, [
    "deriveBits"
  ]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt: salz, iterations: runden },
    material,
    256
  );
  return new Uint8Array(bits);
}
var bremseSchluessel = (benutzer) => `bremse:${benutzer.toLowerCase()}`;
async function gesperrt(kv, benutzer) {
  const stand2 = await kv.get(bremseSchluessel(benutzer));
  return Number(stand2 ?? 0) >= MAX_FEHLVERSUCHE;
}
async function fehlversuch(kv, benutzer) {
  const schluessel2 = bremseSchluessel(benutzer);
  const stand2 = Number(await kv.get(schluessel2) ?? 0) + 1;
  await kv.put(schluessel2, String(stand2), { expirationTtl: SPERRE_SEKUNDEN });
}
async function bremseLoesen(kv, benutzer) {
  await kv.delete(bremseSchluessel(benutzer));
}

// src/mcp/protokoll.ts
var PROTOCOL_VERSION = "2025-06-18";
var SUPPORTED_PROTOCOLS = ["2025-06-18", "2025-03-26", "2024-11-05"];
var result = (id, res) => ({ jsonrpc: "2.0", id, result: res });
var rpcError = (id, code, message) => ({
  jsonrpc: "2.0",
  id: id ?? null,
  error: { code, message }
});
function toolKatalog(tools) {
  return tools.map((t) => ({
    name: t.name,
    title: t.title,
    description: t.description,
    inputSchema: t.inputSchema,
    annotations: t.annotations
  }));
}
async function handleRpc(body, ctx, tools, serverInfo, instructions, prompts = [], ressourcen2 = []) {
  if (Array.isArray(body)) {
    return rpcError(null, -32600, "JSON-RPC-Batches werden von MCP nicht mehr unterst\xFCtzt.");
  }
  const req = body;
  if (!req || req.jsonrpc !== "2.0" || typeof req.method !== "string") {
    return rpcError(req?.id, -32600, "Kein g\xFCltiger JSON-RPC-2.0-Request.");
  }
  const isNotification = req.id === void 0 || req.id === null;
  switch (req.method) {
    case "initialize": {
      const wanted = req.params?.protocolVersion;
      return result(req.id, {
        protocolVersion: SUPPORTED_PROTOCOLS.includes(wanted) ? wanted : PROTOCOL_VERSION,
        capabilities: {
          tools: { listChanged: false },
          resources: { subscribe: false, listChanged: false },
          prompts: { listChanged: false }
        },
        serverInfo: {
          ...serverInfo,
          icons: [
            { src: `${ctx.origin}/icon.svg`, mimeType: "image/svg+xml", sizes: ["any"] }
          ]
        },
        instructions
      });
    }
    case "notifications/initialized":
    case "notifications/cancelled":
    case "notifications/progress":
      return null;
    case "ping":
      return result(req.id, {});
    case "tools/list":
      return result(req.id, { tools: toolKatalog(tools) });
    case "resources/list":
      return result(req.id, {
        resources: ressourcen2.map((r) => ({
          uri: r.uri,
          name: r.name,
          title: r.title,
          description: r.description,
          mimeType: r.mimeType
        }))
      });
    case "resources/templates/list":
      return result(req.id, { resourceTemplates: [] });
    case "resources/read": {
      const uri = String(req.params?.uri ?? "");
      const r = ressourcen2.find((x) => x.uri === uri);
      if (!r) return rpcError(req.id, -32602, `Unbekannte Ressource '${uri}'.`);
      try {
        return result(req.id, {
          contents: [{ uri: r.uri, mimeType: r.mimeType, text: await r.lesen(ctx) }]
        });
      } catch (e) {
        return rpcError(req.id, -32603, e.message);
      }
    }
    case "prompts/list":
      return result(req.id, {
        prompts: prompts.map((p) => ({
          name: p.name,
          title: p.title,
          description: p.description,
          arguments: p.arguments ?? []
        }))
      });
    case "prompts/get": {
      const name = String(req.params?.name ?? "");
      const prompt = prompts.find((p) => p.name === name);
      if (!prompt) return rpcError(req.id, -32602, `Unbekannter Prompt '${name}'.`);
      const fehlend = (prompt.arguments ?? []).filter((a) => a.required && !String(req.params?.arguments?.[a.name] ?? "").trim()).map((a) => a.name);
      if (fehlend.length) {
        return rpcError(req.id, -32602, `Pflichtargument fehlt: ${fehlend.join(", ")}.`);
      }
      try {
        const text = await prompt.bauen(req.params?.arguments ?? {}, ctx);
        return result(req.id, {
          description: prompt.description,
          messages: [{ role: "user", content: { type: "text", text } }]
        });
      } catch (e) {
        return rpcError(req.id, -32603, e.message);
      }
    }
    case "tools/call": {
      const name = req.params?.name;
      const tool = tools.find((t) => t.name === name);
      if (!tool) return rpcError(req.id, -32602, `Unbekanntes Tool '${name}'.`);
      try {
        const daten = await tool.handler(req.params?.arguments ?? {}, ctx);
        return result(req.id, {
          content: [{ type: "text", text: JSON.stringify(daten, null, 2) }],
          isError: false
        });
      } catch (e) {
        const err = e;
        return result(req.id, {
          content: [{ type: "text", text: `Fehler in ${name}: ${err.message}` }],
          isError: true
        });
      }
    }
    default:
      if (isNotification) return null;
      return rpcError(req.id, -32601, `Methode '${req.method}' wird nicht unterst\xFCtzt.`);
  }
}

// src/mcp/prompts.ts
init_vorlagen();

// src/daten/objekte.ts
init_basis();
function faelligkeit(letztesDatum, intervallMonate) {
  if (!letztesDatum) {
    return { faellig_am: "", zustand: "ueberfaellig", tage: null, nie_geprueft: true };
  }
  const faellig_am = monateSpaeter(letztesDatum, intervallMonate);
  const tage = tageBis(faellig_am);
  return {
    faellig_am,
    zustand: tage < 0 ? "ueberfaellig" : tage <= 30 ? "bald" : "ok",
    tage,
    nie_geprueft: false
  };
}
function frueheste(liste) {
  let beste = { faellig_am: "", zustand: "ok", tage: null, nie_geprueft: false };
  let gefunden = false;
  for (const f of liste) {
    if (!gefunden) {
      beste = f;
      gefunden = true;
      continue;
    }
    if (f.nie_geprueft && !beste.nie_geprueft) beste = f;
    else if (!f.nie_geprueft && !beste.nie_geprueft && f.faellig_am < beste.faellig_am) beste = f;
  }
  return gefunden ? beste : { faellig_am: "", zustand: "ok", tage: null, nie_geprueft: false };
}
