// src/reihenfolge.ts
function natuerlichVergleich(a, b) {
  const teile = (s) => s.match(/\d+|\D+/g) ?? [];
  const ta = teile(a.trim().toLowerCase());
  const tb = teile(b.trim().toLowerCase());
  for (let i = 0; i < Math.max(ta.length, tb.length); i++) {
    const x = ta[i];
    const y = tb[i];
    if (x === void 0) return -1;
    if (y === void 0) return 1;
    const xn = /^\d/.test(x);
    const yn = /^\d/.test(y);
    if (xn && yn) {
      const d = Number(x) - Number(y);
      if (d) return d;
    } else if (x !== y) {
      return x < y ? -1 : 1;
    }
  }
  return 0;
}
function anteil(liste, trifft) {
  return liste.length ? liste.filter(trifft).length / liste.length : 0;
}
function wegSortieren(mitPosition, start, seitenverhaeltnis) {
  const punkt = (b) => ({ x: (b.x ?? 0) * seitenverhaeltnis, y: b.y ?? 0 });
  const abstand = (p, q) => Math.hypot(p.x - q.x, p.y - q.y);
  const offen = [...mitPosition];
  let hier = start !== null ? { x: start.x * seitenverhaeltnis, y: start.y } : (
    /* ohne Startpunkt: das oberste Bauteil, bei Gleichstand das linkeste */
    punkt(
      offen.reduce(
        (best, b) => (b.y ?? 0) < (best.y ?? 0) || (b.y ?? 0) === (best.y ?? 0) && (b.x ?? 0) < (best.x ?? 0) ? b : best
      )
    )
  );
  const weg = [];
  while (offen.length) {
    let besterIndex = 0;
    let beste = Infinity;
    for (let i = 0; i < offen.length; i++) {
      const d = abstand(hier, punkt(offen[i]));
      if (d < beste) {
        beste = d;
        besterIndex = i;
      }
    }
    const naechstes = offen.splice(besterIndex, 1)[0];
    weg.push(naechstes);
    hier = punkt(naechstes);
  }
  let versuche = 0;
  let verbessert = true;
  while (verbessert && versuche < 200) {
    verbessert = false;
    for (let i = 0; i < weg.length - 2 && versuche < 200; i++) {
      for (let k = i + 2; k < weg.length && versuche < 200; k++) {
        versuche++;
        const a = punkt(weg[i]);
        const b = punkt(weg[i + 1]);
        const c = punkt(weg[k]);
        const d = k + 1 < weg.length ? punkt(weg[k + 1]) : null;
        const vorher = abstand(a, b) + (d ? abstand(c, d) : 0);
        const nachher = abstand(a, c) + (d ? abstand(b, d) : 0);
        if (nachher + 1e-9 < vorher) {
          const stueck = weg.slice(i + 1, k + 1).reverse();
          weg.splice(i + 1, stueck.length, ...stueck);
          verbessert = true;
        }
      }
    }
  }
  return weg;
}
function laufreihenfolge(bauteile, geschosse) {
  const nachGeschoss = /* @__PURE__ */ new Map();
  for (const g of geschosse) nachGeschoss.set(g.id, g);
  const gruppen = /* @__PURE__ */ new Map();
  for (const b of bauteile) {
    const schluessel3 = b.geschoss_id ?? "";
    const liste = gruppen.get(schluessel3);
    if (liste) liste.push(b);
    else gruppen.set(schluessel3, [b]);
  }
  const rang = (schluessel3) => schluessel3 === "" ? Number.MAX_SAFE_INTEGER : nachGeschoss.get(schluessel3)?.reihenfolge ?? 0;
  const schluessel2 = [...gruppen.keys()].sort((a, b) => {
    const d = rang(a) - rang(b);
    return d !== 0 ? d : a < b ? -1 : 1;
  });
  const out = [];
  for (const s of schluessel2) {
    const gruppe = gruppen.get(s);
    const g = nachGeschoss.get(s);
    if (anteil(gruppe, (b) => String(b.raumnummer ?? "").trim() !== "") >= 0.7) {
      const mit = gruppe.filter((b) => String(b.raumnummer ?? "").trim() !== "");
      const ohne = gruppe.filter((b) => String(b.raumnummer ?? "").trim() === "");
      mit.sort((a, b) => natuerlichVergleich(a.raumnummer, b.raumnummer) || a.nr - b.nr);
      ohne.sort((a, b) => a.nr - b.nr);
      out.push(...mit, ...ohne);
      continue;
    }
    if (anteil(gruppe, (b) => b.x !== null && b.y !== null) >= 0.7) {
      const mit = gruppe.filter((b) => b.x !== null && b.y !== null);
      const ohne = gruppe.filter((b) => b.x === null || b.y === null);
      const verhaeltnis = g?.plan_breite && g?.plan_hoehe ? g.plan_breite / g.plan_hoehe : 1;
      const start = g && g.start_x !== null && g.start_x !== void 0 && g.start_y !== null && g.start_y !== void 0 ? { x: g.start_x, y: g.start_y } : null;
      ohne.sort((a, b) => a.nr - b.nr);
      out.push(...wegSortieren(mit, start, verhaeltnis), ...ohne);
      continue;
    }
    out.push(...[...gruppe].sort((a, b) => a.nr - b.nr));
  }
  return out;
}

