async function naechsteNr(db, objektId) {
  const zeile = await db.prepare("SELECT COALESCE(MAX(nr), 0) AS m FROM bauteile WHERE objekt_id = ?").bind(objektId).first();
  return (zeile?.m ?? 0) + 1;
}
async function bauteilAnlegen(db, daten) {
  const t = jetzt();
  const nr = daten.nr ?? await naechsteNr(db, daten.objekt_id);
  const b = {
    id: ulid(t),
    objekt_id: daten.objekt_id,
    geschoss_id: daten.geschoss_id ?? null,
    tuertyp_id: daten.tuertyp_id ?? null,
    nr,
    kennung: daten.kennung ?? "",
    art: daten.art,
    bezeichnung: daten.bezeichnung ?? "",
    raumnummer: daten.raumnummer ?? "",
    raum: daten.raum ?? "",
    flur: daten.flur ?? "",
    felder: daten.felder ?? {},
    x: daten.x ?? null,
    y: daten.y ?? null,
    richtung_grad: daten.richtung_grad ?? null,
    breite_m: daten.breite_m ?? null,
    intervall_monate: daten.intervall_monate ?? null,
    wartungspflichtig: daten.wartungspflichtig ?? 1,
    aktiv: 1,
    quelle: daten.quelle ?? "manuell",
    angelegt_am: t,
    geaendert_am: t
  };
  await db.prepare(
    `INSERT INTO bauteile (id, objekt_id, geschoss_id, tuertyp_id, nr, kennung, art, bezeichnung, raumnummer,
         raum, flur, felder_json, x, y, richtung_grad, breite_m, intervall_monate,
         wartungspflichtig, aktiv, quelle, angelegt_am, geaendert_am)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
  ).bind(
    b.id,
    b.objekt_id,
    b.geschoss_id,
    b.tuertyp_id,
    b.nr,
    b.kennung,
    b.art,
    b.bezeichnung,
    b.raumnummer,
    b.raum,
    b.flur,
    JSON.stringify(b.felder),
    b.x,
    b.y,
    b.richtung_grad,
    b.breite_m,
    b.intervall_monate,
    b.wartungspflichtig,
    b.aktiv,
    b.quelle,
    b.angelegt_am,
    b.geaendert_am
  ).run();
  return b;
}
async function bauteilLesen(db, id) {
  const zeile = await db.prepare("SELECT * FROM bauteile WHERE id = ?").bind(id).first();
  return zeile ? alsBauteil(zeile) : null;
}
async function bauteilPerNr(db, objektId, nr) {
  const zeile = await db.prepare("SELECT * FROM bauteile WHERE objekt_id = ? AND nr = ?").bind(objektId, nr).first();
  return zeile ? alsBauteil(zeile) : null;
}
function kennungNormal(k) {
  return String(k ?? "").toUpperCase().replace(/[\s\-_.]/g, "");
}
async function bauteilPerKennung(db, objektId, kennung) {
  const { results } = await db.prepare("SELECT * FROM bauteile WHERE objekt_id = ? AND kennung <> '' ORDER BY nr").bind(objektId).all();
  const gesucht = kennungNormal(kennung);
  return (results ?? []).map((z) => alsBauteil(z)).filter((b) => kennungNormal(b.kennung) === gesucht);
}
async function bauteilAendern(db, id, patch) {
  const vorher = await bauteilLesen(db, id);
  if (!vorher) return null;
  const felder = BAUTEIL_SPALTEN.filter((s) => patch[s] !== void 0);
  const s\u00E4tze = felder.map((f) => `${f} = ?`);
  const werte = felder.map((f) => patch[f]);
  if (patch.felder !== void 0) {
    const gemischt = { ...vorher.felder };
    for (const [k, v] of Object.entries(patch.felder)) {
      if (v === "" || v === null || v === void 0) delete gemischt[k];
      else gemischt[k] = String(v);
    }
    s\u00E4tze.push("felder_json = ?");
    werte.push(JSON.stringify(gemischt));
  }
  if (!s\u00E4tze.length) return vorher;
  await db.prepare(`UPDATE bauteile SET ${s\u00E4tze.join(", ")}, geaendert_am = ? WHERE id = ?`).bind(...werte, jetzt(), id).run();
  return bauteilLesen(db, id);
}
async function bauteileMitStand(db, objekt, optionen = {}) {
  const { results } = await db.prepare(
    `SELECT b.*,
              (SELECT g.datum FROM pruefungen p JOIN begehungen g ON g.id = p.begehung_id
                 WHERE p.bauteil_id = b.id ORDER BY p.geprueft_am DESC LIMIT 1) AS letztes_datum,
              (SELECT p.ergebnis FROM pruefungen p
                 WHERE p.bauteil_id = b.id ORDER BY p.geprueft_am DESC LIMIT 1) AS letztes_ergebnis
         FROM bauteile b
        WHERE b.objekt_id = ? ${optionen.auch_stillgelegte ? "" : "AND b.aktiv = 1"}
        ORDER BY b.nr`
  ).bind(objekt.id).all();
  return (results ?? []).map((z) => {
    const zeile = z;
    const b = alsBauteil(zeile);
    const letztes = zeile.letztes_datum ?? "";
    return {
      ...b,
      letzte_pruefung: letztes,
      letztes_ergebnis: zeile.letztes_ergebnis ?? "",
      stand: faelligkeit(letztes || null, b.intervall_monate ?? objekt.intervall_monate)
    };
  });
}
function inLaufreihenfolge(bauteile, geschosse) {
  return laufreihenfolge(bauteile, geschosse);
}
function istFaellig(b) {
  if (!b.aktiv || !b.wartungspflichtig) return false;
  return b.stand.nie_geprueft || (b.stand.tage ?? 0) <= 0;
}

