function zusatzfelderLesen(text) {
  const out = [];
  for (const zeile of text.split("\n")) {
    const roh = zeile.trim();
    if (!roh) continue;
    const pflicht4 = roh.endsWith("*");
    const ohneStern = pflicht4 ? roh.slice(0, -1).trim() : roh;
    const [links, rechts] = ohneStern.split("=");
    const schluessel2 = (links ?? "").trim().toUpperCase().replace(/\s+/g, "_");
    if (!schluessel2) continue;
    out.push({ schluessel: schluessel2, label: (rechts ?? links).trim(), pflicht: pflicht4 });
  }
  return out;
}

